import * as React from "react"
import { cva } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { UI_I18N, type UILocale } from "@/lib/ui-i18n"
import { Badge } from "@/components/ui/badge"
import { Card, CardAction, CardContent, CardHeader } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

import {
  type CardStatSize,
  type FormatOptions,
  applyFormat,
  cardStatLabelVariants,
  cardStatValueVariants,
  cardStatDescriptionVariants,
  cardStatHeaderIconVariants,
  cardStatContentGapVariants,
  cardStatBadgePaddingVariants,
} from "@/lib/card-stats-shared"

// ── Types ──
export interface CardStatHeatbarZone {
  label: string
  color: string
  max: number
}

export interface CardStatHeatbarProps extends FormatOptions {
  label: string
  value: number
  min?: number
  max?: number
  description?: string
  zones?: CardStatHeatbarZone[]
  icon?: React.ElementType
  size?: CardStatSize
  className?: string
  loading?: boolean
  empty?: boolean
  locale?: UILocale
}

// ── Variants ──
export const cardStatTrackHVariants = cva("", {
  variants: {
    size: {
      sm: "h-2",
      md: "h-3",
      lg: "h-4",
    },
  },
  defaultVariants: { size: "sm" },
})

export const cardStatMarkerTopVariants = cva("", {
  variants: {
    size: {
      sm: "top-1.5",
      md: "top-2.5",
      lg: "top-3",
    },
  },
  defaultVariants: { size: "sm" },
})

// ── Helpers ──
const DEFAULT_HEATBAR_ZONES: CardStatHeatbarZone[] = [
  { label: "Poor", color: "var(--color-risk-1)", max: 25 },
  { label: "Fair", color: "var(--color-risk-2)", max: 50 },
  { label: "Good", color: "var(--color-risk-3)", max: 75 },
  { label: "Excellent", color: "var(--color-risk-4)", max: 100 },
]

export function CardStatHeatbar({
  label,
  value,
  min = 0,
  max = 100,
  description,
  zones: zonesProp,
  icon: Icon,
  size = "sm",
  className,
  loading,
  empty,
  locale,
  ...fmt
}: CardStatHeatbarProps) {
  const zones =
    zonesProp ??
    (locale
      ? [
          {
            label: UI_I18N[locale].cardStatGauge.poor,
            color: "var(--color-risk-1)",
            max: 25,
          },
          {
            label: UI_I18N[locale].cardStatGauge.fair,
            color: "var(--color-risk-2)",
            max: 50,
          },
          {
            label: UI_I18N[locale].cardStatGauge.good,
            color: "var(--color-risk-3)",
            max: 75,
          },
          {
            label: UI_I18N[locale].cardStatGauge.excellent,
            color: "var(--color-risk-4)",
            max: 100,
          },
        ]
      : DEFAULT_HEATBAR_ZONES)
  if (loading) {
    return (
      <Card size="sm" className={className} data-slot="card-stat-heatbar">
        <CardHeader className="flex flex-row items-center justify-between">
          <Skeleton className="h-3 w-28 rounded-md" />
          <Skeleton
            className={cn(cardStatHeaderIconVariants({ size }), "rounded-md")}
          />
        </CardHeader>
        <CardContent
          className={cn("flex flex-col", cardStatContentGapVariants({ size }))}
          data-slot="card-stat-heatbar-skeleton"
        >
          <div className="flex items-baseline justify-between">
            <Skeleton className="h-7 w-28" />
            <Skeleton className="h-5 w-20 rounded-full" />
          </div>
          <div className="flex flex-col gap-2 pb-6">
            <Skeleton
              className={cn(cardStatTrackHVariants({ size }), "rounded-full")}
            />
            <div className="flex justify-between px-0.5">
              {[...Array(4)].map((_, i) => (
                <Skeleton key={i} className="h-2 w-8 rounded" />
              ))}
            </div>
          </div>
          <Skeleton className="h-3 w-40 rounded-md" />
        </CardContent>
      </Card>
    )
  }

  if (empty) {
    return (
      <Card size="sm" className={className} data-slot="card-stat-heatbar">
        <CardHeader className="flex flex-row items-center justify-between">
          <span
            className={cn(
              "truncate text-muted-foreground",
              cardStatLabelVariants({ size })
            )}
          >
            {label}
          </span>
          {Icon && (
            <CardAction className="text-muted-foreground">
              <Icon
                className={cardStatHeaderIconVariants({ size })}
                aria-hidden
              />
            </CardAction>
          )}
        </CardHeader>
        <CardContent
          className={cn("flex flex-col", cardStatContentGapVariants({ size }))}
          data-slot="card-stat-heatbar-empty"
        >
          <div className="flex items-baseline justify-between">
            <p
              className={cn(
                cardStatValueVariants({ size }),
                "text-muted-foreground/25"
              )}
            >
              —
            </p>
            <Badge
              variant="outline"
              className={cn(
                "text-muted-foreground/60",
                cardStatBadgePaddingVariants({ size }),
                cardStatDescriptionVariants({ size })
              )}
            >
              {locale ? UI_I18N[locale].cardStatGauge.pending : "Pending"}
            </Badge>
          </div>
          <div className="relative pb-10">
            <div
              className={cn(
                "flex overflow-hidden rounded-full",
                cardStatTrackHVariants({ size })
              )}
            >
              {zones.map((zone, i) => {
                const prevMax = i === 0 ? 0 : zones[i - 1].max
                const segW = zone.max - prevMax
                return (
                  <div
                    key={zone.label}
                    style={{ width: `${segW}%`, backgroundColor: zone.color }}
                    className={cn(
                      "opacity-15",
                      i === 0 && "rounded-l-full",
                      i === zones.length - 1 && "rounded-r-full"
                    )}
                  />
                )
              })}
            </div>
            <div className="absolute top-8 flex w-full justify-between px-0.5">
              {zones.map((z) => (
                <span
                  key={z.label}
                  className={cn(
                    "leading-none text-muted-foreground/40",
                    cardStatDescriptionVariants({ size })
                  )}
                >
                  {z.label}
                </span>
              ))}
            </div>
          </div>
          {description && (
            <p
              className={cn(
                "text-muted-foreground/40",
                cardStatDescriptionVariants({ size })
              )}
            >
              {description}
            </p>
          )}
        </CardContent>
      </Card>
    )
  }

  const display = applyFormat(value, { locale, ...fmt })
  const pct = Math.min(100, Math.max(0, ((value - min) / (max - min)) * 100))
  const activeZone = zones.find((z) => pct <= z.max) ?? zones[zones.length - 1]

  return (
    <Card size="sm" className={className} data-slot="card-stat-heatbar">
      <CardHeader className="flex flex-row items-center justify-between">
        <span
          className={cn(
            "truncate text-muted-foreground",
            cardStatLabelVariants({ size })
          )}
        >
          {label}
        </span>
        {Icon && (
          <CardAction className="text-muted-foreground">
            <Icon
              className={cardStatHeaderIconVariants({ size })}
              aria-hidden
            />
          </CardAction>
        )}
      </CardHeader>
      <CardContent
        className={cn("flex flex-col", cardStatContentGapVariants({ size }))}
        data-slot="card-stat-heatbar"
      >
        <div className="flex items-baseline justify-between">
          <p className={cardStatValueVariants({ size })}>{display}</p>
          <span
            className={cn(
              "rounded-full font-semibold text-white",
              cardStatBadgePaddingVariants({ size }),
              cardStatDescriptionVariants({ size })
            )}
            style={{ backgroundColor: activeZone.color }}
            aria-hidden
          >
            {activeZone.label}
          </span>
        </div>

        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger asChild>
              <div className="relative cursor-default pb-10 select-none">
                <div
                  role="progressbar"
                  aria-valuenow={value}
                  aria-valuemin={min}
                  aria-valuemax={max}
                  aria-label={label}
                  className={cn(
                    "flex overflow-hidden rounded-full",
                    cardStatTrackHVariants({ size })
                  )}
                >
                  {zones.map((zone, i) => {
                    const prevMax = i === 0 ? 0 : zones[i - 1].max
                    const segW = zone.max - prevMax
                    return (
                      <div
                        key={zone.label}
                        style={{
                          width: `${segW}%`,
                          backgroundColor: zone.color,
                        }}
                        className={cn(
                          "opacity-80",
                          i === 0 && "rounded-l-full",
                          i === zones.length - 1 && "rounded-r-full"
                        )}
                      />
                    )
                  })}
                </div>

                <div
                  className={cn(
                    "absolute -translate-x-1/2 pt-0.5",
                    cardStatMarkerTopVariants({ size })
                  )}
                  style={{ left: `${pct}%` }}
                >
                  <svg width="10" height="6" viewBox="0 0 10 6" aria-hidden>
                    <polygon
                      points="5,0 10,6 0,6"
                      style={{ fill: activeZone.color }}
                    />
                  </svg>
                </div>

                <div className="absolute top-8 flex w-full justify-between px-0.5">
                  {zones.map((z) => (
                    <span
                      key={z.label}
                      className={cn(
                        "leading-none text-muted-foreground",
                        cardStatDescriptionVariants({ size })
                      )}
                    >
                      {z.label}
                    </span>
                  ))}
                </div>
              </div>
            </TooltipTrigger>
            <TooltipContent side="top">
              {display} — {activeZone.label}
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>

        {description && (
          <p
            className={cn(
              "text-muted-foreground",
              cardStatDescriptionVariants({ size })
            )}
          >
            {description}
          </p>
        )}
      </CardContent>
    </Card>
  )
}
